/* Lookup table for tilt data */
typedef struct {
    const char *path;
    const uint8_t *data;
    size_t size;
} EmbeddedEntry;

static const EmbeddedEntry tilt_entries[] = {
    { "data/tilt/left_only", tilt_left_only, 1024 },
    { "data/tilt/right_only", tilt_right_only, 1024 },
    { "data/tilt/up_only", tilt_up_only, 1024 },
    { "data/tilt/up_left", tilt_up_left, 1024 },
    { "data/tilt/up_right", tilt_up_right, 1024 },
};

#define TILT_COUNT (sizeof(tilt_entries) / sizeof(tilt_entries[0]))

const uint8_t *embedded_tilt_table(const char *path, size_t *out_size) {
    for (size_t i = 0; i < TILT_COUNT; i++) {
        if (strcmp(path, tilt_entries[i].path) == 0) {
            *out_size = tilt_entries[i].size;
            return tilt_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
